draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // house
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.rect(W/2-50, H/2-50, 100, 100);
  ctx.stroke();

  // dog
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2+20, 10, 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+30);
  ctx.lineTo(W/2-10, H/2+50);
  ctx.lineTo(W/2+10, H/2+50);
  ctx.stroke();

  // family
  ctx.beginPath();
  ctx.arc(W/2-30, H/2-20, 10, 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2+30, H/2-20, 10, 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2, H/2-40, 10, 0, 2*Math.PI);
  ctx.fill();

  // dog tail
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+50);
  ctx.lineTo(W/2+20+10*Math.sin(t), H/2+70);
  ctx.stroke();

  // family arms
  ctx.beginPath();
  ctx.moveTo(W/2-30, H/2-10);
  ctx.lineTo(W/2-10+10*Math.cos(t), H/2);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2+30, H/2-10);
  ctx.lineTo(W/2+10-10*Math.cos(t), H/2);
  ctx.stroke();

  ctx.restore();
}
